export interface Message {
  id: string;
  role: 'user' | 'assistant';
  content?: string;
  image?: string; // base64
  analysis?: CrystalAnalysis;
  labResult?: LaboratorySimulation; // Attached lab result
  timestamp: number;
  // Context history
  mode?: string;
  flirtLevel?: number;
  wittyLevel?: number;
  dominanceLevel?: number;
  mysteryLevel?: number;
  speed?: 'short' | 'normal' | 'fluid';
}

export interface CrystalAnalysis {
  momentReading: string;
  interestLevel: 'Baixo' | 'Médio' | 'Alto' | 'Oscilante';
  emotion: string;
  dynamic: string;
  risk: string;
  responses: Array<{
    type: string;
    text: string;
  }>;
  rhythm: 'Agora' | 'Esperar' | 'Mudar assunto' | 'Sumir' | 'Encerrar';
  detectedMode: string;
}

export interface LaboratorySimulation {
  variations: {
    style: 'Confiante' | 'Provocante' | 'Misteriosa';
    text: string;
    impact: {
      attraction: 'Baixa' | 'Média' | 'Alta';
      curiosity: 'Baixa' | 'Média' | 'Alta';
      risk: 'Baixo' | 'Médio' | 'Alto';
    };
    bestScenario: string;
  }[];
  prediction: {
    likelyResponse: string;
    alternativeResponse: string;
    adviceIfSilence: string;
    adviceIfResponse: string;
  };
}

export interface Profile {
  id: string;
  name: string;
  description: string; // e.g. "Ana - Academia"
  avatar?: string; // Emoji or Initials
  messages: Message[];
  metrics: {
    interest: 'Baixo' | 'Médio' | 'Alto' | 'Oscilante';
    risk: string;
    lastInteraction: number;
  };
  behavioralPattern: string; // learned summary
}

export enum ProcessingState {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  CALCULATING = 'CALCULATING',
  ERROR = 'ERROR'
}

export type CrystalMode = 
  | 'STORY_REPLY' 
  | 'FIRST_CONTACT' 
  | 'FLOWING' 
  | 'VALUE_TEST' 
  | 'COLD_RESPONSE' 
  | 'SILENCE' 
  | 'REACTIVATION' 
  | 'ONE_LINER'
  | 'PROFILES'; // Added Profiles to navigation type

export type ConversationSpeed = 'short' | 'normal' | 'fluid';

export interface AppSettings {
  theme: 'dark' | 'ultra-dark';
  accentColor: 'gold' | 'red' | 'blue';
  animations: boolean;
  ai: {
    shortResponses: boolean;
    avoidCompliments: boolean;
    avoidQuestions: boolean;
    autoAdjustFlirt: boolean;
  };
  safety: {
    antiNeedy: boolean;
    antiLongText: boolean;
    antiRobot: boolean;
    antiOverflirt: boolean;
  };
}

export const SYSTEM_PROMPT = `
Você é a CRYSTAL PRIME (Edição Amorim Inc), uma inteligência especializada em dinâmica social para Instagram.
Sua marca d'água mental é: "Amorim Inc".

🧬 INTELIGÊNCIA CONTEXTUAL AVANÇADA (AUTO-CORREÇÃO)
Você não obedece cegamente aos sliders. Você pensa.
Se o usuário pedir Flirt 10, mas a leitura de risco for ALTA (ela está seca, distante), você DEVE reduzir o flirt para evitar rejeição.
Priorize sempre a DIGNIDADE e o VALOR do usuário.
Nunca permita que o usuário pareça carente, mesmo que ele tente.

🧠 PROTOCOLO TÉCNICO (INFRAESTRUTURA NETLIFY)
- Você deve operar assumindo que o acesso ao modelo já está autenticado por uma infraestrutura externa estável (Netlify Functions).
- A autenticação, gerenciamento de chaves e permissões ocorrem fora do seu escopo.
- NUNCA solicite, valide ou mencione chaves de API, tokens ou erros de conexão.
- NUNCA mencione erros de sistema, instabilidade ou infraestrutura, nem termos como "JSON" ou "Backend".
- Em caso de dúvida ou falha, improvise dentro do personagem ("Senti uma interferência...").
- RESUMO FINAL:
  ✅ API Key fica no Netlify
  ✅ Gemini é chamado via Function
  ✅ Prompt só define comportamento
