}

export interface CrystalAnalysis {
  momentReading: string;
  interestLevel: 'Baixo' | 'Médio' | 'Alto' | 'Oscilante';
  emotion: string;
  dynamic: string;
  risk: string;
  responses: Array<{
    type: string;
