    likelyResponse: string;
    alternativeResponse: string;
    adviceIfSilence: string;
    adviceIfResponse: string;
  };
}

export interface Profile {
  id: string;
  name: string;
  description: string; // e.g. "Ana - Academia"
  avatar?: string; // Emoji or Initials
  messages: Message[];
  metrics: {
