export const analyzeContent = async (
  text: string, 
  imageBase64: string | undefined,
  mode: CrystalMode,
  flirtLevel: number,
  wittyLevel: number,
  dominanceLevel: number,
  mysteryLevel: number,
  speed: ConversationSpeed,
  settings: AppSettings,
  profileContext?: Profile
): Promise<CrystalAnalysis> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-pro-preview"; 

  const parts: any[] = [];

  let profileInstruction = "";
  if (profileContext && profileContext.name !== "Geral") {
    profileInstruction = `
    👤 PERFIL ATIVO: ${profileContext.name} (${profileContext.description})
    HISTÓRICO: O usuário já trocou ${profileContext.messages.length} mensagens.
    PADRÃO DELA: ${profileContext.behavioralPattern || "Ainda em análise"}
    RISCO ANTERIOR: ${profileContext.metrics.risk}
    `;
  }

  const contextInstruction = `
  ⚡ AMORIM INC - PARÂMETROS DE OPERAÇÃO:

  MODO: ${mode}
  ${profileInstruction}

  🎚️ SLIDERS (Intenção do Usuário):
  - Flirt: ${flirtLevel}/10
  - Lábia: ${wittyLevel}/10
  - Dominância: ${dominanceLevel}/10
  - Mistério: ${mysteryLevel}/10

  ⚡ VELOCIDADE: ${speed.toUpperCase()}

  ⚙️ CONFIGURAÇÕES GLOBAIS (RESPEITE RIGOROSAMENTE):
  - Respostas Curtas: ${settings.ai.shortResponses ? 'ATIVADO (Seja breve)' : 'OFF'}
  - Zero Elogios Físicos: ${settings.ai.avoidCompliments ? 'ATIVADO (Proibido chamar de linda/gata)' : 'OFF'}
  - Evitar Perguntas: ${settings.ai.avoidQuestions ? 'ATIVADO (Prefira afirmações)' : 'OFF'}
  - Auto-Ajuste de Risco: ${settings.ai.autoAdjustFlirt ? 'ATIVADO (Reduza flirt se houver risco)' : 'OFF'}
  - Anti-Carência: ${settings.safety.antiNeedy ? 'ATIVADO' : 'OFF'}

  ⚠️ ATENÇÃO: Se a leitura de risco for alta, ignore os sliders altos e proteja o valor do usuário (Auto-Correção).
  `;

  parts.push({ text: contextInstruction });

  if (imageBase64) {
    const cleanBase64 = imageBase64.split(',')[1] || imageBase64;
    parts.push({
      inlineData: {
        mimeType: "image/jpeg",
        data: cleanBase64
      }
    });
  }

  if (text) {
    parts.push({ text });
  }

  if (parts.length === 1) {
    throw new Error("No content to analyze.");
  }

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: parts
      },
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.75, 
      }
    });

    const responseText = response.text;
    if (!responseText) throw new Error("Empty response from Crystal Prime.");

    const analysis = JSON.parse(responseText) as CrystalAnalysis;
    return analysis;

  } catch (error) {
    console.error("Crystal Prime Error:", error);
    throw error;
  }
};

export const regenerateContent = async (
  originalText: string,
  imageBase64: string | undefined,
  previousResponses: { type: string, text: string }[],
  mode: CrystalMode,
  settings: AppSettings
): Promise<{ responses: { type: string, text: string }[] }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-pro-preview";

  const parts: any[] = [];

  const contextInstruction = `
  INPUT ORIGINAL:
  "${originalText}"

  MODO: ${mode}

  ⛔ RESPOSTAS ANTERIORES (NÃO REPETIR ESTAS):
  ${previousResponses.map(r => `- ${r.text}`).join('\n')}

  ⚙️ CONFIGS:
  - Respostas Curtas: ${settings.ai.shortResponses ? 'ON' : 'OFF'}
  - Anti-Gado: ${settings.ai.avoidCompliments ? 'ON' : 'OFF'}
  `;

  parts.push({ text: contextInstruction });

  if (imageBase64) {
     const cleanBase64 = imageBase64.split(',')[1] || imageBase64;
    parts.push({
      inlineData: {
        mimeType: "image/jpeg",
        data: cleanBase64
      }
    });
  }

  try {
    const response = await ai.models.generateContent({
      model,
      contents: { parts },
      config: {
        systemInstruction: SYSTEM_PROMPT + "\n" + REGENERATE_PROMPT,
        responseMimeType: "application/json",
        responseSchema: regenerateSchema,
        temperature: 0.85, // Slightly higher for variation
      }
    });

    if (!response.text) throw new Error("Failed to regenerate");
    return JSON.parse(response.text);
  } catch (error) {
    console.error("Regeneration Error:", error);
    throw error;
  }
};

export const runLaboratory = async (
  contextText: string,
  analysis: CrystalAnalysis,
  profileContext: Profile | undefined,
  settings: AppSettings
): Promise<LaboratorySimulation> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const model = "gemini-3-pro-preview"; 

  const parts: any[] = [];

  let profileInfo = "";
  if (profileContext) {
    profileInfo = `Perfil: ${profileContext.name}. Nível de Interesse: ${profileContext.metrics.interest}.`;
  }

  parts.push({ 
    text: `INPUT ORIGINAL: "${contextText}"
    ANÁLISE INICIAL: ${JSON.stringify(analysis)}
    CONTEXTO DE PERFIL: ${profileInfo}

    Execute a simulação do laboratório agora.` 
  });

  try {
    const response = await ai.models.generateContent({
      model,
      contents: { parts },
      config: {
        systemInstruction: SYSTEM_PROMPT + "\n" + LAB_PROMPT,
        responseMimeType: "application/json",
        responseSchema: labSchema,
        temperature: 0.8
      }
    });

    if(!response.text) throw new Error("Failed to generate lab results");
    return JSON.parse(response.text) as LaboratorySimulation;

  } catch (e) {
    console.error("Lab Error", e);
    throw e;
  }
}

import React from 'react';
import { Copy, Check, Sparkles, ChevronRight, RefreshCw } from 'lucide-react';

interface ResponseOption {
  type: string;
  text: string;
}

interface ResponseOptionsProps {
  responses: ResponseOption[];
  onRegenerate?: () => void;
  isRegenerating?: boolean;
}

const ResponseOptions: React.FC<ResponseOptionsProps> = ({ responses, onRegenerate, isRegenerating }) => {
  const [copiedIndex, setCopiedIndex] = React.useState<number | null>(null);

  const handleCopy = (text: string, index: number) => {
    navigator.clipboard.writeText(text);
    setCopiedIndex(index);
    setTimeout(() => setCopiedIndex(null), 2000);
  };

  return (
    <div className="space-y-3 w-full animate-fade-in">
      <div className="flex items-center justify-between px-1">
        <h3 className="text-[10px] font-mono text-crystal-gold uppercase tracking-widest flex items-center gap-2">
          <Sparkles size={10} className="text-crystal-gold" />
          Opções Geradas
        </h3>

        {onRegenerate && (
          <button 
            onClick={onRegenerate}
            disabled={isRegenerating}
            className={`flex items-center gap-1.5 px-2 py-1 rounded-full border border-crystal-800 bg-[#0a0a0a] hover:border-crystal-gold/50 hover:text-crystal-gold transition-all group ${isRegenerating ? 'opacity-50 cursor-not-allowed' : ''}`}
          >
            <RefreshCw size={10} className={`text-gray-500 group-hover:text-crystal-gold ${isRegenerating ? 'animate-spin' : ''}`} />
            <span className="text-[8px] font-mono text-gray-500 group-hover:text-crystal-gold uppercase">Regerar</span>
          </button>
        )}
      </div>

      {/* Horizontal Scroll Container */}
      <div className="flex overflow-x-auto gap-4 pb-4 -mx-1 px-1 snap-x snap-mandatory hide-scrollbar">
        {responses.map((res, idx) => (
          <div 
            key={idx} 
            onClick={() => handleCopy(res.text, idx)}
            className={`flex-none w-[85%] sm:w-[300px] snap-center group relative bg-crystal-900 border transition-all duration-300 rounded-xl p-5 cursor-pointer flex flex-col justify-between
              ${copiedIndex === idx 
                ? 'border-green-500/50 shadow-[0_0_20px_rgba(16,185,129,0.1)]' 
                : 'border-crystal-800 hover:border-crystal-gold/40 hover:bg-[#0c0c0c] hover:shadow-[0_0_20px_rgba(212,175,55,0.05)]'}
            `}
          >
            <div>
              <div className="flex justify-between items-start mb-3">
                <span className="text-[9px] font-mono text-gray-500 uppercase tracking-wider border border-gray-800 px-2 py-0.5 rounded-full">{res.type}</span>
                <div className="text-gray-600 group-hover:text-crystal-gold transition-colors">
                  {copiedIndex === idx ? <Check size={14} className="text-green-500" /> : <Copy size={14} />}
                </div>
              </div>
              <p className="text-gray-200 font-medium text-sm leading-relaxed select-none whitespace-pre-wrap">{res.text}</p>
            </div>

            <div className="mt-4 pt-3 border-t border-gray-900/50 flex justify-end">
              <span className="text-[8px] text-gray-700 font-mono uppercase">
                {copiedIndex === idx ? 'Copiado!' : 'Toque para copiar'}
              </span>
            </div>

            {copiedIndex === idx && (
              <div className="absolute inset-0 rounded-xl border border-green-500/20 animate-pulse pointer-events-none"></div>
            )}
          </div>
        ))}
        {/* Spacer for right padding in scroll */}
        <div className="w-2 flex-none"></div>
      </div>
    </div>
  );
};

